        "+ checkQuality() : boolean",
        "+ updateDescription(newDescription : string)",
        "+ assignCategory(category : string)"
      ]
    },
    {
      "name": "Client",
      "attributes": [
        "+ Name : string",
        "+ HomeAddress : string",
